glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
vec4 vert () {
  v_uv = a_texCoord;
  v_color = a_color;
  return cc_matViewProj * vec4(a_position, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
uniform sampler2D digitAtlas;
layout(std140) uniform DigitUBO {
  vec2 gridSize;
  vec2 digitInfo;
  vec2 cellPad;
  vec2 lineWidth;
  vec4 gridLineColor;
  vec4 detailParams;
};
vec4 frag () {
  vec2 texelSize = 1.0 / gridSize;
  vec2 cellIdx = floor(v_uv * gridSize);
  vec2 cellCenter = (cellIdx + 0.5) * texelSize;
  float digitIndex = floor(texture(cc_spriteTexture, cellCenter).r * 255.0 + 0.5);
  if (digitIndex < 0.5) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  }
  float detailOp = detailParams.x;
  if (detailOp < 0.001) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  }
  vec2 cellLocal = fract(v_uv * gridSize);
  vec2 fw = vec2(0.001);
  vec2 lw = max(lineWidth, fw);
  float leftEdge  = 1.0 - smoothstep(lw.x - fw.x, lw.x + fw.x, cellLocal.x);
  float rightEdge = smoothstep(1.0 - lw.x - fw.x, 1.0 - lw.x + fw.x, cellLocal.x);
  float topEdge   = 1.0 - smoothstep(lw.y - fw.y, lw.y + fw.y, cellLocal.y);
  float botEdge   = smoothstep(1.0 - lw.y - fw.y, 1.0 - lw.y + fw.y, cellLocal.y);
  float isLine = max(max(leftEdge, rightEdge), max(topEdge, botEdge));
  float padX = cellPad.x;
  float padY = cellPad.y;
  bool inDigitArea = cellLocal.x >= padX && cellLocal.x <= 1.0 - padX
                  && cellLocal.y >= padY && cellLocal.y <= 1.0 - padY;
  vec4 digitColor = vec4(0.0);
  if (inDigitArea) {
    float localX = (cellLocal.x - padX) / (1.0 - 2.0 * padX);
    float localY = (cellLocal.y - padY) / (1.0 - 2.0 * padY);
    float atlasCols = digitInfo.x;
    float atlasRows = digitInfo.y;
    float idx = digitIndex - 1.0;
    float col = mod(idx, atlasCols);
    float row = floor(idx / atlasCols);
    float digitU = (col + localX) / atlasCols;
    float digitV = (row + localY) / atlasRows;
    digitColor = texture(digitAtlas, vec2(digitU, digitV)) * v_color;
  }
  if (digitColor.a > 0.01) {
    digitColor.a *= detailOp;
    return digitColor;
  } else if (isLine > 0.01) {
    vec4 lineColor = gridLineColor;
    lineColor.a *= isLine * v_color.a * detailOp;
    return lineColor;
  }
  return vec4(0.0, 0.0, 0.0, 0.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 v_uv;
varying vec4 v_color;
vec4 vert () {
  v_uv = a_texCoord;
  v_color = a_color;
  return cc_matViewProj * vec4(a_position, 1.0);
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D cc_spriteTexture;
uniform sampler2D digitAtlas;
   uniform vec2 gridSize;
   uniform vec2 digitInfo;
   uniform vec2 cellPad;
   uniform vec2 lineWidth;
   uniform vec4 gridLineColor;
   uniform vec4 detailParams;
vec4 frag () {
  vec2 texelSize = 1.0 / gridSize;
  vec2 cellIdx = floor(v_uv * gridSize);
  vec2 cellCenter = (cellIdx + 0.5) * texelSize;
  float digitIndex = floor(texture2D(cc_spriteTexture, cellCenter).r * 255.0 + 0.5);
  if (digitIndex < 0.5) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  }
  float detailOp = detailParams.x;
  if (detailOp < 0.001) {
    return vec4(0.0, 0.0, 0.0, 0.0);
  }
  vec2 cellLocal = fract(v_uv * gridSize);
  vec2 fw = vec2(0.001);
  vec2 lw = max(lineWidth, fw);
  float leftEdge  = 1.0 - smoothstep(lw.x - fw.x, lw.x + fw.x, cellLocal.x);
  float rightEdge = smoothstep(1.0 - lw.x - fw.x, 1.0 - lw.x + fw.x, cellLocal.x);
  float topEdge   = 1.0 - smoothstep(lw.y - fw.y, lw.y + fw.y, cellLocal.y);
  float botEdge   = smoothstep(1.0 - lw.y - fw.y, 1.0 - lw.y + fw.y, cellLocal.y);
  float isLine = max(max(leftEdge, rightEdge), max(topEdge, botEdge));
  float padX = cellPad.x;
  float padY = cellPad.y;
  bool inDigitArea = cellLocal.x >= padX && cellLocal.x <= 1.0 - padX
                  && cellLocal.y >= padY && cellLocal.y <= 1.0 - padY;
  vec4 digitColor = vec4(0.0);
  if (inDigitArea) {
    float localX = (cellLocal.x - padX) / (1.0 - 2.0 * padX);
    float localY = (cellLocal.y - padY) / (1.0 - 2.0 * padY);
    float atlasCols = digitInfo.x;
    float atlasRows = digitInfo.y;
    float idx = digitIndex - 1.0;
    float col = mod(idx, atlasCols);
    float row = floor(idx / atlasCols);
    float digitU = (col + localX) / atlasCols;
    float digitV = (row + localY) / atlasRows;
    digitColor = texture2D(digitAtlas, vec2(digitU, digitV)) * v_color;
  }
  if (digitColor.a > 0.01) {
    digitColor.a *= detailOp;
    return digitColor;
  } else if (isLine > 0.01) {
    vec4 lineColor = gridLineColor;
    lineColor.a *= isLine * v_color.a * detailOp;
    return lineColor;
  }
  return vec4(0.0, 0.0, 0.0, 0.0);
}
void main() { gl_FragColor = frag(); }
